{"implementation":"def solve(case):
    nodes = list(case.get("nodes", []))
    required_symbols = set(case.get("required_symbols", []))

    by_id = {node.get("id"): node for node in nodes}
    children = {}
    for node in nodes:
        children.setdefault(node.get("parent"), []).append(node.get("id"))

    contains_required = {}

    def subtree_contains_required(node_id):
        if node_id in contains_required:
            return contains_required[node_id]
        node = by_id[node_id]
        found = node.get("symbol") in required_symbols
        for child_id in children.get(node_id, []):
            if subtree_contains_required(child_id):
                found = True
        contains_required[node_id] = found
        return found

    for node in nodes:
        node_id = node.get("id")
        if node_id is not None:
            subtree_contains_required(node_id)

    removed = set()

    def mark_removed(node_id):
        removed.add(node_id)
        for child_id in children.get(node_id, []):
            mark_removed(child_id)

    for node in nodes:
        node_id = node.get("id")
        if node_id in removed:
            continue
        if node.get("removable") and not contains_required.get(node_id, False):
            mark_removed(node_id)

    removed_node_ids = []
    retained_node_ids = []
    for node in nodes:
        node_id = node.get("id")
        if node_id in removed:
            removed_node_ids.append(node_id)
        else:
            retained_node_ids.append(node_id)

    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }
"}
